mapper.select:
SELECT COUNT(*)
FROM SYS_JOB_RUN_LOG
WHERE job_id = #{jobId}

mapper.update:
UPDATE SYS_JOB_RUN_LOG
SET status = 'SUCCESS',
    end_time = #{endTime}
WHERE id = #{id}

UPDATE SYS_JOB_RUN_LOG
SET status = 'FAILED',
    end_time = #{endTime},
    error_msg = #{errorMsg}
WHERE id = #{id}
